actions.script:
import org.moqui.entity.EntityCondition
def ef = ec.entity

// ===== ZE-DASH date-range filter =====
// NOTE: contacts have no reliable "created/became-a-customer" date in the data (party/party_role
// carry only last_updated_stamp), so a date filter over the directory counts would be a no-op OR a
// fabrication. The honest time dimension for a Contacts view is customer *transaction activity*:
// finalised sales invoices (invoiceDate, org-scoped) — same "finalised sale" basis as SalesDashboard.
// The range drives ONLY the Customer Activity chart, Top Customers, and the "active in range" stat.
// The Customers/Suppliers directory totals above stay "current" (MARUTHI-safe).
def _sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def _now = ec.user.nowTimestamp
def _todayStr = _sdf.format(_now)
if (!dashDate) dashDate = ''
if (!dashDateTo) dashDateTo = ''
dayStart = null; dayEndExcl = null
if (dashDate) {
    if (!dashDateTo) dashDateTo = dashDate
    if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
    dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
    def _ce = java.util.Calendar.getInstance(); _ce.setTime(java.sql.Timestamp.valueOf(dashDateTo + " 00:00:00")); _ce.add(java.util.Calendar.DAY_OF_MONTH, 1)
    dayEndExcl = new java.sql.Timestamp(_ce.getTimeInMillis())
}
def _cw = java.util.Calendar.getInstance(); _cw.setTime(_now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def _weekStartStr = _sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(); _cm.setTime(_now); _cm.set(java.util.Calendar.DAY_OF_MONTH,1); def _monthStartStr = _sdf.format(_cm.getTime())
def _c30 = java.util.Calendar.getInstance(); _c30.setTime(_now); _c30.add(java.util.Calendar.DAY_OF_MONTH,-29); def _last30Str = _sdf.format(_c30.getTime())
urlAll = "?"; urlToday = "?dashDate="+_todayStr+"&dashDateTo="+_todayStr
urlWeek = "?dashDate="+_weekStartStr+"&dashDateTo="+_todayStr
urlMonth = "?dashDate="+_monthStartStr+"&dashDateTo="+_todayStr
url30 = "?dashDate="+_last30Str+"&dashDateTo="+_todayStr
presetActive = 'all'
if (dashDate) {
    presetActive = 'custom'
    if (dashDateTo == _todayStr) {
        if (dashDate == _todayStr) presetActive='today'
        else if (dashDate == _weekStartStr) presetActive='week'
        else if (dashDate == _monthStartStr) presetActive='month'
        else if (dashDate == _last30Str) presetActive='last30'
    }
}
// window = selected range, else last 6 months
def _acStart; def _acEnd
if (dayStart) { _acStart = dayStart; _acEnd = dayEndExcl }
else {
    def _c6 = java.util.Calendar.getInstance(); _c6.setTime(_now); _c6.set(java.util.Calendar.DAY_OF_MONTH,1); _c6.add(java.util.Calendar.MONTH,-5); _acStart = new java.sql.Timestamp(_c6.getTimeInMillis())
    def _ce2 = java.util.Calendar.getInstance(); _ce2.setTime(_now); _ce2.add(java.util.Calendar.DAY_OF_MONTH,1); _acEnd = new java.sql.Timestamp(_ce2.getTimeInMillis())
}
def _daily = ((_acEnd.getTime() - _acStart.getTime()) / (1000L*60*60*24)) <= 62
def _bfmt = _daily ? new java.text.SimpleDateFormat("yyyy-MM-dd") : new java.text.SimpleDateFormat("yyyy-MM")
def _lfmt = _daily ? new java.text.SimpleDateFormat("dd MMM") : new java.text.SimpleDateFormat("MMM yy")

// one finalised-sales-invoice pass drives all range widgets
def _invs = orgId ? ef.find("mantle.account.invoice.Invoice")
                      .condition("fromPartyId", orgId)
                      .condition("invoiceTypeEnumId", "InvoiceSales")
                      .condition("statusId", EntityCondition.IN, ["InvoiceFinalized","InvoicePmtRecvd"])
                      .condition("invoiceDate", EntityCondition.GREATER_THAN_EQUAL_TO, _acStart)
                      .condition("invoiceDate", EntityCondition.LESS_THAN, _acEnd)
                      .selectField("toPartyId").selectField("invoiceDate")
                      .selectField("totalTaxableAmount").selectField("totalTaxAmount").selectField("roundOffAmount")
                      .list() : []

// build empty daily/monthly buckets across the window
def _keys = []; def _labelByKey = [:]; def _setBy = [:]
def _bc = java.util.Calendar.getInstance(); _bc.setTime(_acStart); def _bendMs = _acEnd.getTime(); int _guard = 0
while (_bc.getTimeInMillis() < _bendMs && _guard < 400) {
    def _k = _bfmt.format(_bc.getTime())
    if (!_labelByKey.containsKey(_k)) { _keys.add(_k); _labelByKey[_k] = _lfmt.format(_bc.getTime()); _setBy[_k] = new HashSet() }
    _bc.add(_daily ? java.util.Calendar.DAY_OF_MONTH : java.util.Calendar.MONTH, 1); _guard++
}
def _custTotal = [:]; def _allCust = new HashSet()
_invs.each {
    if (!it.toPartyId) return
    def _k = _bfmt.format(it.invoiceDate)
    if (_setBy.containsKey(_k)) _setBy[_k].add(it.toPartyId)
    _allCust.add(it.toPartyId)
    def _amt = ((it.totalTaxableAmount ?: 0G) + (it.totalTaxAmount ?: 0G) + (it.roundOffAmount ?: 0G))
    _custTotal[it.toPartyId] = (_custTotal[it.toPartyId] ?: 0G) + _amt
}
def _aclbls=[]; def _acvals=[]
_keys.each { _k -> _aclbls.add("'"+_labelByKey[_k]+"'"); _acvals.add(_setBy[_k].size()) }
acLabelsJson = "["+_aclbls.join(",")+"]"
acValsJson   = "["+_acvals.join(",")+"]"
acActiveInRange = _allCust.size()
acInvCount = _invs.size()
acHasData = _invs.size() > 0
acRangeLabel = dashDate ? (dashDate == dashDateTo ? dashDate : (dashDate + " to " + dashDateTo)) : "last 6 months"

// top customers by finalised sales value in the window
def _ct = _custTotal.entrySet().toList()
_ct.sort { a, b -> (b.value <=> a.value) }
def _topc = _ct.size() > 8 ? _ct.subList(0, 8) : _ct
def _tclbls=[]; def _tcvals=[]
for (e in _topc) {
    def _nm = null
    def _org = ef.find("mantle.party.Organization").condition("partyId", e.key).one()
    if (_org) _nm = _org.organizationName
    if (!_nm) { def _per = ef.find("mantle.party.Person").condition("partyId", e.key).one(); if (_per) _nm = ((_per.firstName ?: '') + ' ' + (_per.lastName ?: '')).trim() }
    if (!_nm) _nm = e.key
    _nm = _nm.toString().replace("'", " ").replace("\"", " ")
    if (_nm.length() > 26) _nm = _nm.substring(0, 26)
    _tclbls.add("'" + _nm + "'")
    _tcvals.add(((e.value ?: 0G) as java.math.BigDecimal).setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
}
tcLabelsJson = "[" + _tclbls.join(",") + "]"
tcValsJson   = "[" + _tcvals.join(",") + "]"
tcHasData    = (_tcvals.size() > 0)

// ZE-DASH layout: switchable widgets (+ cashier role default) + saved drag order
def _roleHidden = ''
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'activity,topcust'
    }
} catch (Exception e) {}
def _pref = ec.user.getPreference('CONTACT_DASH_HIDDEN')
def _hiddenSet = ((_pref != null) ? _pref : _roleHidden).split(',').findAll { it }.toSet()
showMetrics = !_hiddenSet.contains('metrics'); showActivity = !_hiddenSet.contains('activity'); showTopcust = !_hiddenSet.contains('topcust')
w_metrics = showMetrics ? 'Y' : ''; w_activity = showActivity ? 'Y' : ''; w_topcust = showTopcust ? 'Y' : ''
dashOrderCsv = (ec.user.getPreference('CONTACT_DASH_ORDER') ?: '')
urlSettings = dashDate ? ("?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&showSettings=1") : "?showSettings=1"
